def _github_client(client: Any | None) -> tuple[Any, bool]:
    if client is not None:
        return client, False
    token = os.getenv("GITHUB_TOKEN", "")
    if not token:
        raise RuntimeError("GITHUB_TOKEN is required to post a review comment")
    return httpx.Client(
        headers={"Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json",
                 "X-GitHub-Api-Version": "2022-11-28"}, timeout=30,
    ), True

