def validate_evidence_report(report: Any) -> dict[str, Any]:
    """Validate report types and cross-section evidence consistency."""
    if not isinstance(report, dict):
        raise EvidenceReportValidationError("Evidence report must be a JSON object")
    if report.get("schema_version") not in {4, 5, 6}:
        raise EvidenceReportValidationError("Unsupported evidence report schema version")
    normalized = _normalize_legacy_v4(report)
    try:
        EvidenceReportV6.model_validate(normalized)
    except ValidationError as exc:
        details = [
            f"{'.'.join(str(part) for part in error.get('loc', ())) or 'report'}: {error.get('msg', 'invalid value')}"
            for error in exc.errors(include_input=False)
        ]
        raise EvidenceReportValidationError("; ".join(details[:80])) from exc
    return report

def build_dependabot_review_graph(
    *,
    github_client: Any | None = None,
    osv_client: httpx.AsyncClient | None = None,
    model: Any | None = None,
    usage_analyzer: Callable[..., Any] | None = None,
    release_context_lookup: Callable[..., Any] | None = None,
) -> Any:
    """Compile evidence collection, LLM investigation, and optional PR comment nodes."""
    def collect(state: DependabotReviewState) -> dict[str, Any]:
        report = review_dependabot_pull_request(
            state["repository"], state["pull_request"], github_client=github_client,
            osv_client=osv_client, usage_analyzer=usage_analyzer,
            release_context_lookup=release_context_lookup,
        )
        return {"report": report}

    def start(_state: DependabotReviewState) -> dict[str, Any]:
        return {}

    def route_start(state: DependabotReviewState) -> str:
        return "analyze_evidence" if state.get("report") else "collect_evidence"

    def route_after_collection(state: DependabotReviewState) -> str:
        return END if state.get("collect_only") else "analyze_evidence"

    def analyze(state: DependabotReviewState) -> dict[str, Any]:
        report = state["report"]
        try:
            if report.get("schema_version") in {4, 5, 6}:
                validate_evidence_report(report)
            active_model = model
            if active_model is None:
                from vulnerability_agent.dependencies import _model
                active_model = _model()
            review_text = _sanitize_ai_review(report, _model_text(active_model, render_review_prompt(report)))
            return {"review_markdown": review_text,
                    "report": {**report, "ai_review": review_text, "ai_review_status": "complete"}}
        except Exception as exc:
            # Preserve collected test and OSV evidence even when model access
            # fails; never let a failed analysis create a PR comment.
            validation = dict(report.get("validation", {}))
            if isinstance(exc, EvidenceReportValidationError):
                validation.update({"status": "failed", "errors": [str(exc)[:2_000]]})
            failed = {**report, "status": "analysis_failed", "ai_review_status": "failed",
                      "ai_review_error": f"{type(exc).__name__}: {exc}",
                      **({"validation": validation} if validation else {})}
            return {"report": failed}

    def comment(state: DependabotReviewState) -> dict[str, Any]:
        try:
            if state["report"].get("schema_version") in {4, 5, 6}:
                validate_evidence_report(state["report"])
            url = post_idempotent_review_comment(
                state["report"], state["review_markdown"], github_client=github_client,
            )
            return {"comment_url": url, "report": {**state["report"], "review_comment_url": url}}
        except Exception as exc:
            return {"report": {**state["report"], "status": "comment_failed",
                                "comment_error": f"{type(exc).__name__}: {exc}"}}

    def route_after_analysis(state: DependabotReviewState) -> str:
        return "post_comment" if state.get("post_comment") and state.get("review_markdown") else END

    graph = StateGraph(DependabotReviewState)
    graph.add_node("start", start)
    graph.add_node("collect_evidence", collect)
    graph.add_node("analyze_evidence", analyze)
    graph.add_node("post_comment", comment)
    graph.set_entry_point("start")
    graph.add_conditional_edges(
        "start", route_start,
        {"collect_evidence": "collect_evidence", "analyze_evidence": "analyze_evidence"},
    )
    graph.add_conditional_edges(
        "collect_evidence", route_after_collection,
        {"analyze_evidence": "analyze_evidence", END: END},
    )
    graph.add_conditional_edges(
        "analyze_evidence", route_after_analysis,
        {"post_comment": "post_comment", END: END},
    )
    graph.add_edge("post_comment", END)
    return graph.compile()

    review_graph = build_dependabot_review_graph(usage_analyzer=analyze_usage)
    initial_state: dict[str, Any] = {
        "post_comment": args.post_comment,
        "collect_only": args.collect_only,
    }
    if precollected_report is not None:
        initial_state["report"] = precollected_report
    else:
        initial_state.update({"repository": str(repo), "pull_request": args.review_pr})
    review_state = review_graph.invoke(initial_state)
    report = review_state.get("report", {})
except Exception as exc:
    report = {
        "schema_version": 3, "mode": "dependabot_pr_review", "status": "review_failed",
        "repository": str(repo or ""), "pull_request_reference": args.review_pr,
        "error": f"{type(exc).__name__}: {exc}",
        "note": "Review-only workflow; no push, PR creation, merge, or comment was attempted.",
    }

