    misleading = "There are 16 remaining advisory records indicating that langchain 0.2.17 is affected."
    corrected = "There are 16 remaining advisory records across langchain and langchain-core."

    assert _sanitize_ai_review(report, misleading) == ""
    assert _sanitize_ai_review(report, corrected) == corrected

async def _call(self, server: str, repo_path: str, tool: str, arguments: dict[str, Any]) -> str:
    spec = self._config(server, repo_path)
    params = StdioServerParameters(command=spec["command"], args=spec["args"], env=os.environ.copy())
    try:
        async with AsyncExitStack() as stack:
            read, write = await stack.enter_async_context(stdio_client(params))
            session = await stack.enter_async_context(ClientSession(read, write))
            await session.initialize()
            result = await session.call_tool(tool, arguments=arguments)
            if result.isError:
                raise MCPCallError(
                    server, tool, self._content_text(result.content), retryable=False,
                )
            if result.structuredContent:
                # The filesystem server may expose read_text_file as
                # structured content ({"content": "..."}). Returning
                # JSON here makes downstream parsers and patch edits
                # operate on the wrapper instead of the actual file.
                if server == "filesystem" and tool in {"read_text_file", "read_multiple_files"}:
                    structured = result.structuredContent
                    if isinstance(structured, dict):
                        for key in ("content", "text"):
                            value = structured.get(key)
                            if isinstance(value, str):
                                return value
                    if isinstance(structured, str):
                        return structured
                return json.dumps(result.structuredContent, ensure_ascii=False)
            return self._content_text(result.content)
    except MCPCallError:
        raise
    except Exception as exc:
        raise MCPCallError(server, tool, _exception_details(exc), retryable=True) from exc

def call(self, server: str, repo_path: str, tool: str, arguments: dict[str, Any]) -> str:
    """Run an MCP request, retrying one transient server startup failure."""
    for attempt in range(2):
        try:
            return run_async(self._call(server, repo_path, tool, arguments))
        except MCPCallError as exc:
            if not exc.retryable or attempt == 1:
                raise
            logger.warning("Transient MCP %s.%s failure; retrying once: %s", server, tool, exc)
            time.sleep(0.25)
    raise AssertionError("unreachable")

def call(self, server: str, repo_path: str, tool: str, arguments: dict[str, Any]) -> str:
    try:
        root, safe_args = self._authorize(server, tool, repo_path, arguments)
    except MCPPolicyError as exc:
        self._record(server, tool, "denied", str(exc))
        raise
    event_id = self._record(server, tool, "allowed")
    try:
        result = self.client.call(server, str(root), tool, safe_args)
    except Exception as exc:
        # Error messages may echo arguments/source; retain only the class.
        self.audit_log.finalize(event_id, "error", type(exc).__name__)
        raise
    return result

def __init__(
    self,
    storage_path: str | Path,
    *,
    embedding_model: str = DEFAULT_EMBEDDING_MODEL,
    client: Any | None = None,
    embedder: Any | None = None,
) -> None:
    try:
        if client is None:
            from qdrant_client import QdrantClient
            client = QdrantClient
        if embedder is None:
            from fastembed import TextEmbedding
            embedder = TextEmbedding
        from qdrant_client.models import Distance, VectorParams
    except ImportError as exc:
        raise RuntimeError(
            "Code RAG dependencies are missing. Install requirements.txt to use Qdrant retrieval."
        ) from exc
    self.storage_path = Path(storage_path).expanduser().resolve()
    self.storage_path.mkdir(parents=True, exist_ok=True, mode=0o700)
    try:
        os.chmod(self.storage_path, 0o700)
    except OSError:
        pass
    self.client = client(path=str(self.storage_path)) if isinstance(client, type) else client
    self.embedder = embedder(model_name=embedding_model) if isinstance(embedder, type) else embedder
    self.collection_name = "repository_code"
    self._documents: dict[str, list[dict[str, Any]]] = {}
    if not self.client.collection_exists(self.collection_name):
        self.client.create_collection(
            collection_name=self.collection_name,
            vectors_config=VectorParams(size=VECTOR_SIZE, distance=Distance.COSINE),
        )

def index_sources(
    self, repository: str | Path, sources: dict[str, str], *, snapshot_id: str = "",
) -> int:
    """Replace the repository's chunks and persist their local vectors."""
    from reporting import _redact_source

    repo_key = self._repo_key(repository)
    documents: list[dict[str, Any]] = []
    for relative_path, source in sources.items():
        for chunk in chunk_source(
            relative_path, _redact_source(source),
            parser_cache_dir=self.storage_path / "tree-sitter",
        ):
            chunk = _enrich_chunk_metadata(relative_path, source, chunk)
            chunk_id = str(uuid.uuid5(uuid.NAMESPACE_URL, "\0".join((repo_key, chunk["path"], chunk["symbol"], str(chunk["line_start"])))))
            chunk.update({
                "id": chunk_id, "repo_id": repo_key,
                "snapshot_id": snapshot_id,
                "metadata_version": INDEX_METADATA_VERSION,
                "search_text": f"{chunk['path']} {chunk['symbol']} {chunk['content']}",
            })
            documents.append(chunk)
    point_filter = self._repo_filter(repo_key)
    from qdrant_client.models import PointStruct

    self.client.delete(collection_name=self.collection_name, points_selector=point_filter, wait=True)
    if documents:
        vectors = self._embed([str(document["search_text"]) for document in documents])
        points = [
            PointStruct(id=document["id"], vector=vector, payload=document)
            for document, vector in zip(documents, vectors)
        ]
        self.client.upsert(collection_name=self.collection_name, points=points, wait=True)
    self._documents[repo_key] = documents
    return len(documents)

@staticmethod
def _repo_filter(repo_key: str) -> Any:
    from qdrant_client.models import FieldCondition, Filter, MatchValue

    return Filter(must=[FieldCondition(key="repo_id", match=MatchValue(value=repo_key))])

def retrieve(
    self,
    repository: str | Path,
    query: str,
    *,
    limit: int = MAX_RETRIEVAL_RESULTS,
    package_name: str | None = None,
    test_context: bool | None = None,
) -> list[dict[str, Any]]:
    """Combine exact BM25 and local dense results, then favor trace locations."""
    repo_key = self._repo_key(repository)
    documents = self._load_documents(repo_key)
    if not documents or not query.strip():
        return []
    retrieval_query = query
    if package_name:
        retrieval_query = f"{' '.join(package_search_terms(package_name))} {query}"
    lexical = bm25_rank(retrieval_query, documents, limit=50)
    # Preserve the original semantic query for dense ranking. Module-name
    # expansion is useful to BM25 for exact imports, but adding tokens to
    # the embedding can distort concept-level relevance.
    query_vector = self._embed([query])[0]
    points = self.client.query_points(
        collection_name=self.collection_name,
        query=query_vector, query_filter=self._repo_filter(repo_key),
        limit=50, with_payload=True,
    ).points
    dense = [str(point.id) for point in points]
    trace_locations = _trace_locations(query)
    by_id = {str(document["id"]): document for document in documents}
    related: list[str] = []
    if trace_locations:
        for document in documents:
            for filename, line in trace_locations:
                if Path(str(document["path"])).name != filename:
                    continue
                if line is None or int(document["line_start"]) - 5 <= line <= int(document["line_end"]) + 5:
                    related.append(str(document["id"]))
                    break
    # Package-aware qualification can discard generic results after fusion.
    # Rank the existing BM25/dense top-50 candidate pools before filtering;
    # final response size remains bounded by `limit`.
    fused = reciprocal_rank_fusion(lexical, dense, related, limit=50)
    # Exact stack-frame path/line matches are high-confidence evidence;
    # return them before semantic matches when handling a failed attempt.
    ordered_ids = list(dict.fromkeys([*related, *fused]))
    package_symbols: set[str] = set()
    query_test_context = test_context if test_context is not None else bool(
        package_name and re.search(r"\b(test|tests|mock|mocked|fixture)\b", query, re.IGNORECASE)
    )
    if package_name:
        # Keep Qdrant, BM25 and RRF as candidate-generation/ranking lanes,
        # then require package-specific syntax or a literal package
        # reference before a chunk can be returned as usage evidence.
        ordered_ids = _package_ranked_ids(
            documents, ordered_ids, package_name, query=query, test_context=query_test_context,
        )
        modules = {module.casefold() for module in distribution_import_modules(package_name)}
        package_symbols = {
            str(binding.get("binding", ""))
            for item in documents for binding in item.get("import_bindings", [])
            if str(binding.get("module", "")).split(".", 1)[0].casefold() in modules
        }
    results = [by_id[document_id] for document_id in ordered_ids if document_id in by_id][:limit]
    if package_name:
        return [
            {**document, "package_evidence_classification": _package_evidence(
                document, package_name, query=query, package_symbols=package_symbols,
                test_context=query_test_context,
            )}
            for document in results
        ]
    return results

