def chunk_source(
    relative_path: str, source: str, *, parser_cache_dir: str | Path | None = None,
) -> list[dict[str, Any]]:
    """Create safe, source-located chunks for Python and JS/TS files."""
    if not _safe_relative_path(relative_path) or not source.strip():
        return []
    suffix = Path(relative_path).suffix.lower()
    if suffix == ".py":
        chunks = _python_chunks(relative_path, source)
    else:
        chunks = _tree_sitter_chunks(relative_path, source, parser_cache_dir)
        if not chunks:
            chunks = _javascript_fallback_chunks(relative_path, source)
    return chunks or _line_chunks(relative_path, source)

def test_javascript_chunking_preserves_common_declaration_boundaries():
    chunks = chunk_source("src/client.js", """import axios from 'axios';
export function fetchClient(url) {
  return axios.get(url);
}
""")

    assert len(chunks) == 1
    assert chunks[0]["symbol"] == "fetchClient"
    assert chunks[0]["line_start"] == 2

def _line_chunks(relative_path: str, source: str) -> list[dict[str, Any]]:
    """Bounded fallback for unsupported syntax or parser errors."""
    lines = source.splitlines()
    result = []
    start = 0
    while start < len(lines):
        end = min(start + 90, len(lines))
        result.append({
            "path": relative_path, "symbol": f"lines_{start + 1}_{end}",
            "line_start": start + 1, "line_end": end,
            "language": CODE_SUFFIX_LANGUAGE[Path(relative_path).suffix.lower()],
            "content": "\n".join(lines[start:end]),
        })
        start = end
    return result

