def _project_python(repo_path: str | Path, project_root: str | Path | None = None) -> str:
    """Select the configured or repository-local Python interpreter."""
    configured = os.getenv("PYTHON")
    if configured:
        return configured
    roots = [Path(project_root).resolve()] if project_root else []
    worktree_root = Path(repo_path).resolve()
    if worktree_root not in roots:
        roots.append(worktree_root)
    executable_names = ("python.exe", "python") if os.name == "nt" else ("python",)
    for root in roots:
        for environment in (".venv", ".tvenv", "venv", "env"):
            for executable_name in executable_names:
                executable = root / environment / ("Scripts" if os.name == "nt" else "bin") / executable_name
                if executable.is_file():
                    return str(executable)
    return sys.executable

def _safe_child_environment() -> dict[str, str]:
    """Reuse the test runner's allowlist for dependency installation too."""
    from sandbox_runner import SAFE_ENV_KEYS

    environment = {key: os.environ[key] for key in SAFE_ENV_KEYS if key in os.environ}
    environment["CI"] = "true"
    return environment

def _prepare_review_environment(repository: Path) -> dict[str, Any]:
    """Materialize the snapshot's declared dependency versions in its worktree."""
    if (repository / "package-lock.json").is_file() or (repository / "npm-shrinkwrap.json").is_file():
        npm = shutil.which("npm")
        if not npm:
            return {"ready": False, "reason": "npm is not installed", "output": "Install Node.js/npm to run this PR's tests."}
        return _setup_command(repository, [npm, "ci", "--ignore-scripts"])
    if (repository / "uv.lock").is_file():
        uv = shutil.which("uv")
        if not uv:
            return {"ready": False, "reason": "uv is not installed", "output": "Install uv to reproduce the uv.lock environment."}
        return _setup_command(repository, [uv, "sync", "--frozen"])
    if (repository / "poetry.lock").is_file():
        poetry = shutil.which("poetry")
        if not poetry:
            return {"ready": False, "reason": "Poetry is not installed", "output": "Install Poetry to reproduce poetry.lock."}
        environment = _safe_child_environment()
        environment["POETRY_VIRTUALENVS_IN_PROJECT"] = "true"
        try:
            result = subprocess.run(
                [poetry, "install", "--no-interaction", "--no-ansi"], cwd=repository,
                env=environment, capture_output=True, text=True, timeout=600, check=False,
            )
            return {"ready": result.returncode == 0, "command": [poetry, "install", "--no-interaction", "--no-ansi"],
                    "returncode": result.returncode, "output": (result.stdout or "") + (result.stderr or "")}
        except (OSError, subprocess.TimeoutExpired) as exc:
            return {"ready": False, "reason": type(exc).__name__, "output": str(exc)}
    requirements = repository / "requirements.txt"
    if requirements.is_file():
        setup = _setup_command(repository, [sys.executable, "-m", "venv", ".venv"])
        if not setup["ready"]:
            return setup
        python = repository / ".venv" / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
        setup = _setup_command(repository, [str(python), "-m", "pip", "install", "-r", "requirements.txt"])
        if not setup["ready"]:
            return setup
        return _setup_command(repository, [str(python), "-m", "pip", "install", "pytest"])
    return {
        "ready": False,
        "reason": "No supported lockfile or requirements.txt is available to reproduce this snapshot",
        "output": "Tests were not run because the base and PR dependency environments could not be isolated.",
    }

def parse_python_lock(content: str) -> list[dict[str, str]]:
    """Read resolved package records from uv.lock or poetry.lock TOML."""
    try:
        import tomllib
    except ImportError:  # Python 3.10
        import tomli as tomllib  # type: ignore[no-redef]
    data = tomllib.loads(content)
    result: list[dict[str, str]] = []
    for package in data.get("package", data.get("packages", [])):
        name, version = package.get("name"), package.get("version")
        if name and version:
            result.append({"name": str(name), "version": str(version), "ecosystem": "PyPI"})
    return result

def _direct_dependency_names(repository: Path) -> set[tuple[str, str]]:
    """Identify top-level declarations; lock-only packages are transitive clues."""
    direct: set[tuple[str, str]] = set()
    requirements = repository / "requirements.txt"
    if requirements.is_file():
        direct.update(("pypi", item["name"].casefold().replace("_", "-").replace(".", "-"))
                      for item in parse_requirements(requirements.read_text(encoding="utf-8")))
    pyproject = repository / "pyproject.toml"
    if pyproject.is_file():
        try:
            import tomllib
        except ImportError:  # Python 3.10
            import tomli as tomllib  # type: ignore[no-redef]
        try:
            data = tomllib.loads(pyproject.read_text(encoding="utf-8"))
            poetry_deps = data.get("tool", {}).get("poetry", {}).get("dependencies", {})
            direct.update(("pypi", str(name).casefold().replace("_", "-").replace(".", "-"))
                          for name in poetry_deps if str(name).casefold() != "python")
            for group in data.get("tool", {}).get("poetry", {}).get("group", {}).values():
                dependencies = group.get("dependencies", {}) if isinstance(group, dict) else {}
                direct.update(("pypi", str(name).casefold().replace("_", "-").replace(".", "-"))
                              for name in dependencies)
            for requirement in data.get("project", {}).get("dependencies", []) or []:
                match = re.match(r"\s*([A-Za-z0-9_.-]+)", str(requirement))
                if match:
                    direct.add(("pypi", match.group(1).casefold().replace("_", "-").replace(".", "-")))
            for requirements_group in data.get("project", {}).get("optional-dependencies", {}).values():
                for requirement in requirements_group or []:
                    match = re.match(r"\s*([A-Za-z0-9_.-]+)", str(requirement))
                    if match:
                        direct.add(("pypi", match.group(1).casefold().replace("_", "-").replace(".", "-")))
        except (OSError, ValueError):
            pass
    package_json = repository / "package.json"
    if package_json.is_file():
        import json
        try:
            data = json.loads(package_json.read_text(encoding="utf-8"))
            for section in ("dependencies", "devDependencies", "optionalDependencies", "peerDependencies"):
                direct.update(("npm", str(name).casefold()) for name in (data.get(section) or {}))
        except (OSError, ValueError):
            pass
    return direct

def poetry_declared_constraint(content: str, package_name: str) -> Any | None:
    """Find a package constraint in Poetry or PEP 621 project dependency tables."""
    try:
        import tomllib
    except ImportError:  # Python 3.10
        import tomli as tomllib  # type: ignore[no-redef]
    try:
        data = tomllib.loads(content)
    except (ValueError, TypeError) as exc:
        raise ValueError(f"Cannot parse pyproject.toml for dependency verification: {exc}") from exc
    wanted = _normalized_package_name(package_name, "pypi")
    tool = data.get("tool", {}).get("poetry", {})
    tables = [tool.get("dependencies", {})]
    tables.extend(
        group.get("dependencies", {})
        for group in (tool.get("group", {}) or {}).values()
        if isinstance(group, dict)
    )
    for dependencies in tables:
        for name, constraint in (dependencies or {}).items():
            if _normalized_package_name(str(name), "pypi") == wanted:
                return constraint
    project = data.get("project", {})
    requirements = list(project.get("dependencies", []) or [])
    for optional in (project.get("optional-dependencies", {}) or {}).values():
        requirements.extend(optional or [])
    for raw_requirement in requirements:
        try:
            requirement = Requirement(str(raw_requirement))
        except InvalidRequirement:
            continue
        if _normalized_package_name(requirement.name, "pypi") == wanted:
            return str(requirement.specifier) or "*"
    return None

def _dependency_index(repository: Path) -> tuple[set[tuple[str, str]], dict[tuple[str, str], set[tuple[str, str]]]]:
    """Read direct roots and dependency edges from common manifests/lockfiles."""
    roots = _direct_dependency_names(repository)
    edges: dict[tuple[str, str], set[tuple[str, str]]] = {}

    def normalize(ecosystem: str, name: Any) -> tuple[str, str]:
        value = str(name).casefold()
        if ecosystem == "pypi":
            value = value.replace("_", "-").replace(".", "-")
        return ecosystem, value

    python_lock = next((repository / name for name in ("uv.lock", "poetry.lock") if (repository / name).is_file()), None)
    if python_lock:
        try:
            import tomllib
        except ImportError:  # Python 3.10
            import tomli as tomllib  # type: ignore[no-redef]
        try:
            data = tomllib.loads(python_lock.read_text(encoding="utf-8"))
            packages = data.get("package", data.get("packages", []))
            for package in packages:
                parent_name = package.get("name")
                if not parent_name:
                    continue
                parent = normalize("pypi", parent_name)
                dependencies = package.get("dependencies", {})
                if isinstance(dependencies, dict):
                    dependency_names = dependencies.keys()
                elif isinstance(dependencies, list):
                    dependency_names = [entry.get("name") for entry in dependencies if isinstance(entry, dict)]
                else:
                    dependency_names = []
                for dependency_name in dependency_names:
                    if dependency_name:
                        edges.setdefault(parent, set()).add(normalize("pypi", dependency_name))
        except (OSError, ValueError, TypeError):
            pass

    npm_lock = next((repository / name for name in ("npm-shrinkwrap.json", "package-lock.json") if (repository / name).is_file()), None)
    if npm_lock:
        import json
        try:
            data = json.loads(npm_lock.read_text(encoding="utf-8"))
            package_records = data.get("packages") or {}
            for lock_path, package in package_records.items():
                if not isinstance(package, dict):
                    continue
                if lock_path:
                    parts = lock_path.split("node_modules/")
                    parent_name = parts[-1].strip("/") if len(parts) > 1 else package.get("name")
                else:
                    parent_name = "__root__"
                parent = normalize("npm", parent_name) if parent_name else None
                if parent is None:
                    continue
                for section in ("dependencies", "optionalDependencies", "peerDependencies"):
                    for dependency_name in (package.get(section) or {}):
                        edges.setdefault(parent, set()).add(normalize("npm", dependency_name))
        except (OSError, ValueError, TypeError):
            pass

    return roots, edges

def _dependency_changes(base_root: Path, head_root: Path, base_scan: dict[str, Any], head_scan: dict[str, Any]) -> list[dict[str, Any]]:
    """Compare resolved inventories and label packages declared at the top level."""
    def inventory(scan: dict[str, Any]) -> dict[tuple[str, str], str]:
        result: dict[tuple[str, str], str] = {}
        for item in scan.get("resolved_packages", []):
            ecosystem = str(item.get("ecosystem", "")).casefold()
            name = str(item.get("name", "")).casefold()
            if ecosystem == "pypi":
                name = name.replace("_", "-").replace(".", "-")
            result[(ecosystem, name)] = str(item.get("version", ""))
        return result

    before, after = inventory(base_scan), inventory(head_scan)
    base_roots, base_edges = _dependency_index(base_root)
    head_roots, head_edges = _dependency_index(head_root)
    direct = base_roots | head_roots
    edges = {parent: set(children) for parent, children in base_edges.items()}
    for parent, children in head_edges.items():
        edges.setdefault(parent, set()).update(children)
    changes: list[dict[str, Any]] = []

    def constraints_for(target_name: str, paths: list[list[str]], target_is_direct: bool) -> tuple[list[dict[str, str]], str]:
        """Collect constraints imposed by direct declarations and lockfile parents."""
        constraints: dict[tuple[str, str], dict[str, str]] = {}
        expected_parents = {path[-2] for path in paths if len(path) > 1}
        missing_parents = set(expected_parents)
        lock = next((head_root / name for name in ("poetry.lock", "uv.lock") if (head_root / name).is_file()), None)
        if lock:
            try:
                import tomllib
                lock_data = tomllib.loads(lock.read_text(encoding="utf-8"))
                packages = lock_data.get("package", lock_data.get("packages", []))
                by_parent = {str(p.get("name", "")).casefold().replace("_", "-").replace(".", "-"): p
                             for p in packages if isinstance(p, dict)}
                parents = {path[-2] for path in paths if len(path) > 1}
                for parent_name in parents:
                    parent = by_parent.get(parent_name.casefold().replace("_", "-").replace(".", "-"))
                    dependencies = parent.get("dependencies", {}) if parent else {}
                    entries = dependencies.items() if isinstance(dependencies, dict) else (
                        (entry.get("name"), entry) for entry in dependencies if isinstance(entry, dict)
                    ) if isinstance(dependencies, list) else ()
                    for dep_name, raw in entries:
                        normalized = str(dep_name).casefold().replace("_", "-").replace(".", "-")
                        if normalized == target_name:
                            value = raw.get("version", "*") if isinstance(raw, dict) else raw
                            constraints[(parent_name, str(value or "*"))] = {
                                "parent": parent_name, "constraint": str(value or "*"), "source": lock.name,
                            }
                            missing_parents.discard(parent_name)
            except (OSError, ValueError, TypeError):
                pass
        if target_is_direct and (head_root / "pyproject.toml").is_file():
            try:
                declared = poetry_declared_constraint((head_root / "pyproject.toml").read_text(encoding="utf-8"), target_name)
                if declared is not None:
                    constraints[("project", str(declared))] = {
                        "parent": "project", "constraint": str(declared), "source": "pyproject.toml",
                    }
            except (OSError, ValueError):
                pass
        values = [constraints[key] for key in sorted(constraints)]
        complete = bool(values) and not missing_parents and (not target_is_direct or any(item["parent"] == "project" for item in values))
        return values, "complete" if complete else ("partial" if values else "unavailable")

    for ecosystem, name in sorted(before.keys() | after.keys()):
        old, new = before.get((ecosystem, name), ""), after.get((ecosystem, name), "")
        if old == new:
            continue
        target = (ecosystem, name)
        paths = _dependency_paths(direct, edges, target)
        relationship = "direct" if target in direct else ("transitive" if paths else "unknown")
        upgrade_constraints, constraints_status = constraints_for(name, paths, target in head_roots)
        changes.append({
            "package": name,
            "ecosystem": ecosystem,
            "base_version": old or "not present",
            "head_version": new or "removed",
            "relationship": relationship,
            "dependency_paths": paths,
            "upgrade_constraints": upgrade_constraints,
            "upgrade_constraints_status": constraints_status,
        })
    return changes

